@spec arrange_view_spec  src=tests/specs/arrange_view_spec.lua  loc=634  cases=36
@exercises configManager (h.cm), arrangeView (av), commandManager (h.cmgr), arrangeManager (am2)
@surface   cm:set, av:cursorRow, av:cursorCol, av:setCursor, av:setGridSize, av:scroll, av:scrollBy, av:setMaxCol, av:beatPerRow, av:setBeatPerRow, cm:get, av:rowToQN, av:paletteSlot, av:setPaletteSlot, av:focus, av:setFocus, cmgr:push, cmgr:invoke, am2:tracksTakes, av:tracksTakes, av:lassoCandidate, av:selectionSet, av:selectBand, cmgr:pop, av:dropBand, av:setSelection, av:addToSelection, av:toggleSelected, av:isSelected, av:dragCandidate, av:commitDrag, av:qnToRow
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks

# Intent
  arrangeView: in-memory cursor/scroll + persisted beatPerRow, mirroring
  the trackerView/editCursor split (cursor is transient, density persists).

# Helpers
  @fn mkAv(harness)  @ 7-13
  @fn mkArrange(harness, items)  @ 17-36
      -- Build an av over a fake project. items: list of {track, name, pos, len?}.
      -- Tracks are created in first-seen order; beatPerRow is 1 (1 row = 1 QN).
  @fn takeAt(list, startQN)  @ 38-40

# Cases
  @case 'cursor defaults to (0,0); setCursor clamps negatives and floors'  [harness]  @ 53-61
  @case 'scroll defaults to (0,0); setGridSize alone does not move scroll'  [harness]  @ 65-71
  @case 'cursor moving below the visible band scrolls down to follow'  [harness]  @ 75-82
  @case 'cursor moving above the visible band scrolls up to follow'  [harness]  @ 86-94
  @case 'horizontal follow tracks cursorCol against gridCols'  [harness]  @ 98-108
  @case 'setGridSize shrinking the viewport re-follows the cursor in place'  [harness]  @ 112-123
  @case 'scrollBy pans the viewport without moving the cursor'  [harness]  @ 127-136
  @case 'scrollBy clamps to >= 0 and cursor-nav re-follows the cursor'  [harness]  @ 140-151
  @case 'scroll-right stops once the last column is fully visible'  [harness]  @ 155-163
  @case 'a same-dims setGridSize after a wheel-scroll leaves scroll alone'  [harness]  @ 167-175
  @case 'beatPerRow defaults to cm value; setter clamps minimum'  [harness]  @ 179-188
  @case 'setBeatPerRow holds the cursor QN (zoom anchors on cursor) and clamps max'  [harness]  @ 192-204
  @case 'paletteSlot defaults nil; setter clamps to 0..61; nil clears'  [harness]  @ 208-222
  @case 'focus defaults nil; setFocus stores an opaque handle, nil clears'  [harness]  @ 226-235
  @case 'no selection + on-screen cursor: edit acts on the cursor take, leaves it unselected'  [harness]  @ 239-255
  @case 'no selection + off-screen cursor: an edit is a no-op'  [harness]  @ 259-275
  @case 'a held selection wins over the cursor take'  [harness]  @ 279-298
  @case 'lasso selects every take whose span intersects the swept rect'  [harness]  @ 302-318
  @case 'Shift+arrow selects every take the anchor-to-cursor rect covers'  [harness]  @ 322-335
  @case 'Shift+arrow sideways widens the rect into the next column'  [harness]  @ 339-350
  @case 'Shift+arrow back toward the anchor drops what it uncovers'  [harness]  @ 354-368
  @case 'a plain cursor move ends the run, so the next Shift+arrow re-anchors'  [harness]  @ 372-384
  @case 'the band stands through a run and comes down on the next command'  [harness]  @ 388-406
  @case 'a click takes the band down without waiting for a command'  [harness]  @ 410-421
  @case 'dropBand takes the band down and pops its scope'  [harness]  @ 425-435
  @case 'a multi-selection deletes every selected take in one pass'  [harness]  @ 439-453
  @case 'nudge refuses entirely when any selected take is blocked'  [harness]  @ 457-474
  @case 'nudge slides a contiguous selected block without self-collision'  [harness]  @ 478-493
  @case 'a single-target command no-ops on a multi-selection'  [harness]  @ 497-510
  @case 'arrangeClearSelection empties the selection'  [harness]  @ 514-525
  @case 'addToSelection unions handles without duplicating a present one'  [harness]  @ 529-543
  @case 'toggleSelected adds an absent handle and removes a present one'  [harness]  @ 547-560
  @case 'group drag slides the whole selection by one delta'  [harness]  @ 564-580
  @case 'group drag refuses when a member would hit an outside take'  [harness]  @ 584-597
  @case 'group drag with Alt duplicates the block and reselects the copies'  [harness]  @ 601-619
  @case 'qnToRow / rowToQN are inverses through beatPerRow'  [harness]  @ 623-632

